import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import './ProjectDetail.css';

const ProjectDetail = () => {
  const { projectId } = useParams();
  const [activeSection, setActiveSection] = useState('overview');
  const [workshops, setWorkshops] = useState([]);
  const [loadingWorkshops, setLoadingWorkshops] = useState(false);
  
  // --- HEADER STATE (Mega Menu) ---
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- MEGA MENU DATA ---
  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'Indoor Monitor', image: '/sensor_modules/aqicrop.jpeg', link: '/project/intelligent-sensor' },
        { name: 'Outdoor Station', image: '/sensor_modules/aqi1.jpeg', link: '/project/intelligent-sensor' },
        { name: 'Gas Sensors', image: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400', link: '/project/intelligent-sensor' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Flood Alert System', image: '/sensor_modules/river1.jpg', link: '/project/water-level' },
        { name: 'Level Sensors', image: 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=400', link: '/project/water-level' },
        { name: 'Distribution Net', image: '/sensor_modules/distribution.jpeg', link: '/project/digital-water' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'Auto Weather Station', image: '/sensor_modules/weather.jpg', link: '/project/water-level' },
        { name: 'Rain Gauges', image: 'https://images.unsplash.com/photo-1590055531860-6902633df018?w=400', link: '/project/water-level' }
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Starter Kits', image: '/sensor_modules/skill.jpg', link: '/project/startup-skill' },
        { name: 'PCB Workshops', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/project/startup-skill' }
      ]
    }
  };

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [projectId]);

  useEffect(() => {
    if (projectId === 'startup-skill') {
      setLoadingWorkshops(true);
      const API_BASE_URL = process.env.NODE_ENV === 'production'
        ? 'https://aiiot-1.onrender.com'
        : 'http://localhost:8000';

      axios.get(`${API_BASE_URL}/api/workshops/`)
        .then(response => {
          setWorkshops(response.data);
          setLoadingWorkshops(false);
        })
        .catch(error => {
          console.error("Error fetching workshops", error);
          setLoadingWorkshops(false);
        });
    }
  }, [projectId]);

  const projectsData = {
    'intelligent-sensor': {
      title: 'Pollution Intelligence Network',
      subtitle: 'AI-Powered Hyperlocal Monitoring',
      tagline: 'Sensing. Predicting. Protecting.',
      mainImage: '/sensor_modules/aqi1.jpeg',
      description: 'A scalable LoRa-based network designed not just to monitor, but to predict air quality trends using Artificial Intelligence.',
      fullDescription: `We have deployed a validation-ready network that goes beyond simple sensing. By utilizing LoRa technology for long-range communication and advanced AI models, we provide a 4-day AQI forecast.`,
      innovations: [
        { title: 'Comprehensive Sensing', desc: 'Simultaneous detection of PM2.5, PM10, CO, NO2, O3, and NH3.', icon: '🔬' },
        { title: '4-Day AI Forecasting', desc: 'Predicting AQI levels 96 hours ahead.', icon: '🤖' },
        { title: 'Health Risk', desc: 'Dynamic health assessments for at-risk groups.', icon: '❤️' },
        { title: 'LoRa Scalability', desc: 'Long-range network architecture.', icon: '📡' }
      ],
      impacts: [
        { label: 'Pollutants', value: 'PM2.5, PM10, Gases' },
        { label: 'Forecast', value: '4-Days Ahead' },
        { label: 'Tech Stack', value: 'LoRa + AI' },
        { label: 'Network', value: 'Mesh Topology' }
      ]
    },
    'water-level': {
      title: 'River Watch & Flood Alert',
      subtitle: 'Deep Learning Flood Forecasting',
      tagline: 'Predicting the flow. Protecting Kalady.',
      mainImage: '/sensor_modules/weather.jpg',
      description: 'A comprehensive LSTM neural network system for real-time river level forecasting at Kalady.',
      fullDescription: `This project integrates multi-source data—dam operations, rainfall, and historical levels—into a comprehensive LSTM Neural Network.`,
      innovations: [
        { title: 'LSTM Architecture', desc: '3 stacked layers (128→64→32 units).', icon: '🧠' },
        { title: 'Multi-Source Data', desc: 'Integrates Dam operations & rainfall.', icon: '🌊' },
        { title: '6-Hour Prediction', desc: 'Accurate forecasting lead time.', icon: '⏱️' },
        { title: 'Custom Hardware', desc: 'Proprietary Automatic Weather Station.', icon: '⛈️' }
      ],
      impacts: [
        { label: 'Target', value: 'Kalady Region' },
        { label: 'Model', value: 'LSTM Network' },
        { label: 'Lead Time', value: '6 Hours' },
        { label: 'Hardware', value: 'Custom AWS' }
      ]
    },
    'digital-water': {
      title: 'Digital Water Distribution',
      subtitle: 'Community-First Water Management',
      tagline: 'Collaborative solutions for efficient distribution.',
      mainImage: '/sensor_modules/distribution.jpeg',
      description: 'A digital system built on extensive ground studies to monitor and optimize local water distribution.',
      fullDescription: `We conducted comprehensive ground studies by engaging with Assistant Engineers (AE) at KWA Perumbavoor Division.`,
      innovations: [
        { title: 'Stakeholder Collaboration', desc: 'Requirements from KWA officials.', icon: '🤝' },
        { title: 'Ground Study', desc: 'Site visits to Chembarakky Station.', icon: '📍' },
        { title: 'Explainable AI', desc: 'Transparent IoT analysis.', icon: '🤖' },
        { title: 'Community Feedback', desc: 'Integrated reporting channels.', icon: '🗣️' }
      ],
      impacts: [
        { label: 'Partners', value: 'KWA & Panchayat' },
        { label: 'Focus', value: 'Pumping Infra' },
        { label: 'Tech', value: 'Explainable AI' },
        { label: 'Method', value: 'Field Study' }
      ]
    },
    'startup-skill': {
      title: 'Startup Ecosystem & Skills',
      subtitle: 'Empowering the Next Gen',
      tagline: 'Hands-on mastery of IoT & Environment.',
      mainImage: '/sensor_modules/skill.jpg',
      description: 'Establishing multiple training programs across IoT, AI, and embedded systems.',
      fullDescription: `We foster a startup ecosystem by providing students with real-world exposure. From intensive 15-day summer internships to 6-month specialized intern training.`,
      innovations: [
        { title: 'Research Outputs', desc: '1 Patent filed, 2 Papers published.', icon: '📜' },
        { title: 'Internship Program', desc: '15-day intensive training.', icon: '🎓' },
        { title: 'Hands-on Workshops', desc: 'PCB Design, Edge Hardware.', icon: '🛠️' },
        { title: 'Idea Pitching', desc: 'Mentoring startup teams.', icon: '🚀' }
      ],
      impacts: [
        { label: 'Workshops', value: '260+ Students' },
        { label: 'Interns', value: '49+ Trained' },
        { label: 'Research', value: '1 Patent' },
        { label: 'Teams', value: '6 Mentored' }
      ]
    },
  };

  const project = projectsData[projectId];

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 100;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;
      window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
    }
  };

  if (!project) return <div>Loading...</div>;

  return (
    <div className="project-page">
      
      {/* 1. GLOBAL HEADER (MEGA MENU) */}
      <header className="aiiot-header-local">
        <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1.5rem' }}>
          <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '5rem' }}>
            <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '1rem', textDecoration: 'none', zIndex: 1001 }}>
               <div className="logo-box-local"><img src="/logo/logo.png" alt="Logo" style={{height:'100%'}}/></div>
               <span style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b' }}>AI-IoT Innovations</span>
            </Link>

            <div className="desktop-nav-local">
              <Link to="/" className="nav-link-local">Home</Link>
              <div 
                className="mega-menu-wrapper-local"
                onMouseEnter={() => setIsMegaMenuOpen(true)}
                onMouseLeave={() => setIsMegaMenuOpen(false)}
              >
                <Link to="/products" className="nav-link-local product-trigger-local">Products ▾</Link>
                <div className={`mega-menu-container-local ${isMegaMenuOpen ? 'visible' : ''}`}>
                  <div className="mega-menu-sidebar-local">
                    {Object.keys(productMenuData).map((key) => (
                      <div key={key} className={`mega-sidebar-item-local ${activeCategory === key ? 'active' : ''}`} onMouseEnter={() => setActiveCategory(key)}>
                        {key} ›
                      </div>
                    ))}
                  </div>
                  <div className="mega-menu-content-local">
                    <div className="mega-content-header-local">
                      <h4>{productMenuData[activeCategory].title}</h4>
                      <p>{productMenuData[activeCategory].description}</p>
                    </div>
                    <div className="mega-grid-local">
                      {productMenuData[activeCategory].items.map((item, idx) => (
                        <Link to={item.link} key={idx} className="mega-product-card-local">
                           <div className="mega-img-box-local"><img src={item.image} alt={item.name} /></div>
                           <span>{item.name}</span>
                        </Link>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
              <Link to="/homepage" className="nav-link-local">AirAware</Link>
              <a href="#contact" className="nav-btn-primary-local">Get in Touch</a>
            </div>
          </nav>
        </div>
      </header>

      {/* 2. HERO SECTION */}
      

      {/* 5. NEW: "GUARD YOURSELF" POLLUTANT SECTION (Fills Blank Space) */}
      {/* Only show for Air Quality Project */}
      {projectId === 'intelligent-sensor' && (
        <section className="pollutant-section">
          <div className="pollutant-overlay">
            <h2 style={{ fontSize: '2.5rem', fontWeight: '800', marginBottom: '1rem' }}>Breathe Smart <br/> Protect Your Health from Invisible Pollutants!</h2>
            <p style={{ maxWidth: '600px', margin: '0 auto 3rem auto', fontSize: '1.1rem', opacity: 0.9 }}>
              Air pollution causes millions of premature deaths. Our sensors track these invisible threats in real-time.
            </p>
            
            {/* Floating Bubbles */}
            <div className="pollutant-bubbles-container">
               <div className="p-bubble b1">☁️ PM2.5 ↗</div>
               <div className="p-bubble b2">🌫️ PM10 ↗</div>
               <div className="p-bubble b3">🧪 NO2 ↗</div>
               <div className="p-bubble b4">🏭 CO ↗</div>
               <div className="p-bubble b5">💨 SO2 ↗</div>
               <div className="p-bubble b6">⚡ O3 ↗</div>
            </div>
          </div>
        </section>
        
      )}
      <section className="hero-section" style={{ paddingTop: '8rem' }}>
        <div className="container hero-grid">
          <div className="hero-content">
            <span className="hero-tag">Detailed Case Study</span>
            <p className="hero-title">{project.title}</p>
            <p className="hero-desc">{project.description}</p>
            <div style={{ display: 'flex', gap: '1rem' }}>
              <button onClick={() => scrollToSection('innovations')} className="btn-primary">View Features</button>
            </div>
          </div>
          <div className="hero-img-wrapper">
            <img src={project.mainImage} alt={project.title} className="hero-img" />
          </div>
        </div>
      </section>

      {/* 3. STICKY NAV */}
      

      <div className="container">
        {/* 4. OVERVIEW */}
        <section id="overview" className="section-padding">
          <div className="overview-content">
            <h3 style={{ color: '#0ea5e9', fontWeight: 700, textTransform: 'uppercase', fontSize: '0.85rem' }}>Mission Statement</h3>
            <h2 style={{ fontSize: '1.75rem', fontWeight: 800, color: '#1e293b' }}>{project.tagline}</h2>
            <p style={{ fontSize: '1.1rem', lineHeight: 1.7, color: '#475569' }}>{project.fullDescription}</p>
          </div>
        </section>
      </div>

      <div className="container">
        {/* 6. INNOVATIONS / GRID */}
        <section id="innovations" className="section-padding">
          <h2 className="section-title">Key Innovations</h2>
          
          {projectId === 'startup-skill' && workshops.length > 0 ? (
            <div className="innovation-grid">
               {workshops.map((ws) => (
                  <div key={ws.id} className="feature-card">
                     <h3 className="card-title">{ws.title}</h3>
                     <p style={{color:'#0284c7'}}>{ws.event_date_text}</p>
                     <p className="card-desc">{ws.description}</p>
                  </div>
               ))}
            </div>
          ) : (
            <div className="innovation-grid">
              {project.innovations.map((item, idx) => (
                <div key={idx} className="feature-card">
                  <div className="icon-box">{item.icon}</div>
                  <h3 className="card-title">{item.title}</h3>
                  <p className="card-desc">{item.desc}</p>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>

      {/* 7. UPGRADED IMPACT SECTION (Full Width Image) */}
      <section id="impact" className="impact-parallax-section" style={{ backgroundImage: `url(${project.mainImage})` }}>
        <div className="impact-overlay">
          <div className="container">
            <h2 style={{ color: 'white', fontSize: '2.5rem', fontWeight: 800, marginBottom: '3rem' }}>Measurable Impact</h2>
            <div className="impact-grid-dark">
              {project.impacts.map((stat, idx) => (
                <div key={idx} className="stat-box-dark">
                  <div className="stat-value-dark">{stat.value}</div>
                  <div className="stat-label-dark">{stat.label}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* 8. CONTACT */}
      <div className="container">
        <section id="contact" className="contact-section">
          <h2>Collaboration</h2>
          <a href="mailto:contact@aiiot.edu" className="btn-primary" style={{ textDecoration: 'none', borderRadius: '2rem' }}>Get in Touch</a>
        </section>
      </div>

    </div>
  );
};

export default ProjectDetail;
